@startuml
class School {
  +name : string
}

class Person {
  +firstName : string
  +lastName : string
}

class Teacher extends Person {
  +emailAddress : string
}

class Student extends Person {
}

class ClassGroup {
  +name : string
}

class Classroom {
  +name : string
  +capacity : int
}

class Room {
  +name : string
}

class Classroom extends Room {}

class Gym extends Room {
  +size : float
}

class TeachingAssignment {
  +hours : int
}

School "1" -- "0..3" Teacher : works at
School "1" -- "0..1" Teacher : principal
School "1" *-- "*" Room : consists of
Student "1" -- "1" ClassGroup : is in
ClassGroup "1" -- "1" Classroom : is assigned to
ClassGroup "10..31" -- "1" Student : contains
@enduml

